    public static IReadOnlyList<string> SupportedLanguages => Languages;

    public static string Translate(string text, string language)
    {
        int languageIndex = Array.IndexOf(Languages, language);
        if (languageIndex < 0) languageIndex = 1;

        foreach (var row in Texts)
        {
            int sourceIndex = Array.IndexOf(row, text);
            if (sourceIndex >= 0) return row[languageIndex];
        }

        return text;
    }

    public static string Format(string format, string language, params object[] values)
        => string.Format(Translate(format, language), values);

    public static void Apply(DependencyObject root, string language)
    {
        var visited = new HashSet<DependencyObject>();
        Visit(root);

        void Visit(DependencyObject element)
        {
            if (!visited.Add(element)) return;

            if (element is Window window)
                window.Title = Translate(GetOriginal(element, nameof(Window.Title), window.Title), language);
            if (element is TextBlock textBlock &&
                !BindingOperations.IsDataBound(textBlock, TextBlock.TextProperty))
                textBlock.Text = Translate(GetOriginal(element, nameof(TextBlock.Text), textBlock.Text), language);

            if (element is ContentControl content && content.Content is string contentText &&
                !BindingOperations.IsDataBound(content, ContentControl.ContentProperty))
                content.Content = Translate(GetOriginal(element, nameof(ContentControl.Content), contentText), language);

            if (element is HeaderedContentControl headered && headered.Header is string header &&
                !BindingOperations.IsDataBound(headered, HeaderedContentControl.HeaderProperty))
    headered.Header = Translate(GetOriginal(element, nameof(HeaderedContentControl.Header), header), language);
            if (element is ToggleSwitch toggle)
            {
                if (toggle.OnContent is string on)
                    toggle.OnContent = Translate(GetOriginal(element, nameof(ToggleSwitch.OnContent), on), language);
                if (toggle.OffContent is string off)
                    toggle.OffContent = Translate(GetOriginal(element, nameof(ToggleSwitch.OffContent), off), language);
            }
            if (element is Control control)
            {
                var placeholder = control.GetValue(ControlHelper.PlaceholderTextProperty) as string;
                if (placeholder != null)
                    control.SetValue(ControlHelper.PlaceholderTextProperty,
                        Translate(GetOriginal(element, "PlaceholderText", placeholder), language));
                var controlHeader = control.GetValue(ControlHelper.HeaderProperty) as string;
                if (controlHeader != null)
                    control.SetValue(ControlHelper.HeaderProperty,
                        Translate(GetOriginal(element, "ControlHeader", controlHeader), language));
            }
            if (element is FrameworkElement frameworkElement &&
                frameworkElement.GetValue(FrameworkElement.ToolTipProperty) is string toolTip)
                frameworkElement.SetValue(FrameworkElement.ToolTipProperty,
                    Translate(GetOriginal(element, nameof(FrameworkElement.ToolTip), toolTip), language));
            if (element is FrameworkElement elementWithContextMenu && elementWithContextMenu.ContextMenu != null)
                Visit(elementWithContextMenu.ContextMenu);
            if (element is DataGrid grid)
            {
                foreach (var column in grid.Columns)
                    if (column.Header is string columnHeader)
                    {
                        var original = OriginalColumnHeaders.GetValue(column, _ => new TextSnapshot(columnHeader));
                        column.Header = Translate(original.Value, language);
                    }
            }

            foreach (var child in LogicalTreeHelper.GetChildren(element).OfType<DependencyObject>())
                Visit(child);

            if (element is Visual or System.Windows.Media.Media3D.Visual3D)
            {
                int count = VisualTreeHelper.GetChildrenCount(element);
                for (int index = 0; index < count; index++)
                    Visit(VisualTreeHelper.GetChild(element, index));
            }
        }
    }

    private static string GetOriginal(DependencyObject element, string property, string current)
    {
        var values = OriginalText.GetValue(element, _ => new Dictionary<string, string>());
        if (!values.TryGetValue(property, out var original))
        {
            original = current;
            values.Add(property, original);
        }
        return original;
    }
}